import base64
import json
import os
from typing import Any, Dict, List, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _read_image_bytes(image: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(image, (bytes, bytearray)):
        return bytes(image)
    if not isinstance(image, str):
        raise TypeError("image must be a file path, base64 string, or bytes")

    if os.path.exists(image) and os.path.isfile(image):
        with open(image, "rb") as f:
            return f.read()

    try:
        return base64.b64decode(image, validate=True)
    except Exception as e:
        raise ValueError("image string must be a valid file path or base64-encoded image") from e


def _normalize_labels(labels: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized = []
    for item in labels or []:
        normalized.append(
            {
                "name": item.get("Name"),
                "confidence": float(item.get("Confidence", 0.0)),
                "parents": [p.get("Name") for p in item.get("Parents", []) if isinstance(p, dict)],
                "instances": [
                    {
                        "bounding_box": inst.get("BoundingBox"),
                        "confidence": float(inst.get("Confidence", 0.0)),
                    }
                    for inst in item.get("Instances", [])
                    if isinstance(inst, dict)
                ],
            }
        )
    return normalized


def _normalize_text(detections: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized = []
    for item in detections or []:
        if item.get("Type") == "LINE":
            normalized.append(
                {
                    "text": item.get("DetectedText", ""),
                    "confidence": float(item.get("Confidence", 0.0)),
                    "id": item.get("Id"),
                    "parent_id": item.get("ParentId"),
                }
            )
    return normalized


def _is_policy_sensitive(labels: List[Dict[str, Any]], text: List[Dict[str, Any]]) -> Dict[str, Any]:
    label_names = {l["name"].lower() for l in labels if l.get("name")}
    text_blob = " ".join(t["text"] for t in text if t.get("text")).lower()

    sensitive_label_keywords = {
        "nudity",
        "explicit nudity",
        "sexual activity",
        "sexual content",
        "explicit sexual content",
        "violence",
        "weapon",
        "firearm",
        "knife",
        "blood",
        "drug",
        "alcohol",
        "tobacco",
        "self-harm",
        "suicide",
        "hate symbol",
        "gore",
        "explosive",
    }
    sensitive_text_keywords = {
        "porn",
        "nsfw",
        "sex",
        "nude",
        "naked",
        "kill",
        "suicide",
        "bomb",
        "gun",
        "knife",
        "drug",
        "cocaine",
        "heroin",
        "meth",
        "hate",
        "white power",
        "heil",
        "blood",
    }

    matched_labels = sorted([name for name in label_names if any(k in name for k in sensitive_label_keywords)])
    matched_text = sorted([k for k in sensitive_text_keywords if k in text_blob])

    unsafe = bool(matched_labels or matched_text)
    reasons = []
    if matched_labels:
        reasons.append({"type": "label_match", "matches": matched_labels})
    if matched_text:
        reasons.append({"type": "text_match", "matches": matched_text})

    return {"unsafe": unsafe, "reasons": reasons}


def check_image_for_unsafe_content(image: Union[str, bytes, bytearray]) -> Dict[str, Any]:
    """
    Checks an image for unsafe or policy-sensitive visual content using Amazon Rekognition.

    Input:
        image: file path, base64-encoded string, or raw image bytes.

    Returns:
        Dict with labels, detected text, and a simple unsafe/policy-sensitive assessment.
    """
    image_bytes = _read_image_bytes(image)

    rekognition = boto3.client("rekognition")

    try:
        label_resp = rekognition.detect_labels(
            Image={"Bytes": image_bytes},
            MaxLabels=50,
            MinConfidence=70.0,
        )
        text_resp = rekognition.detect_text(Image={"Bytes": image_bytes})
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Amazon Rekognition request failed: {e}") from e

    labels = _normalize_labels(label_resp.get("Labels", []))
    detected_text = _normalize_text(text_resp.get("TextDetections", []))
    assessment = _is_policy_sensitive(labels, detected_text)

    return {
        "provider": "amazon_rekognition",
        "labels": labels,
        "text": detected_text,
        "assessment": assessment,
        "raw": {
            "label_response": label_resp,
            "text_response": text_resp,
        },
    }
